"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["56674"],{70477(e){e.exports=JSON.parse('{"id":"FIN-147","slug":"selling-expense","term":"Selling Expense","also_known_as":[],"difficulty":"Beginner","definition":"A selling expense is a cost incurred to market and sell a business\'s products or services, such as advertising, sales staff pay, commissions and delivery to customers.","explanation":["Selling expenses are one group of operating expenses. They cover everything involved in finding customers, persuading them to buy and getting products to them.","Common selling expenses include advertising and promotions, salaries and commissions of sales staff, sales travel, the cost of showrooms or retail stores used for selling, packaging for shipment and delivery costs to customers.","On the income statement, selling expenses are often combined with general and administrative expenses into a single line called selling, general and administrative expenses, or SG&A.","For example, a company might spend 90,000 on advertising, 150,000 on sales staff salaries and commissions and 30,000 on deliveries in a year, giving selling expenses of 270,000.","Businesses watch selling expenses relative to revenue. If sales rise faster than selling expenses, marketing is becoming more efficient. If selling expenses rise without a matching increase in sales, the business may be spending too much to win customers."],"note":"","total":1500,"prev":{"slug":"seller-financing","term":"Seller Financing"},"next":{"slug":"semi-variable-cost","term":"Semi-Variable Cost"}}')}}]);